// bcf-test-tester: what `[ ]` really receives vs what `[[ ]]` does, for the same $x.
// Pick a value for x and a comparison. Three cards: [ $x … ] (unquoted), [ "$x" … ] (quoted), [[ $x … ]].
// Each shows the arguments [ receives (after word splitting + globbing), the exit status and bash's real error.
// Results were generated by running every combination in real bash (folder contains notes.md and script.sh).
// input: { x?: "" | "hello" | "a b" | "*" | "10" | "abc"  (default "a b"),
//          op?: "eq_str" | "eq_num" | "n" | "z" | "lt" | "glob"  (default "eq_str") }

const DATA = {"|eq_str|unq":[2,"bash: [: =: unary operator expected",["=","hello"]],"|eq_str|q":[1,"",["","=","hello"]],"|eq_str|dbl":[1,"",null],"|eq_num|unq":[2,"bash: [: -eq: unary operator expected",["-eq","10"]],"|eq_num|q":[2,"bash: [: : integer expression expected",["","-eq","10"]],"|eq_num|dbl":[1,"",null],"|n|unq":[0,"",["-n"]],"|n|q":[1,"",["-n",""]],"|n|dbl":[1,"",null],"|z|unq":[0,"",["-z"]],"|z|q":[0,"",["-z",""]],"|z|dbl":[0,"",null],"|lt|unq":[1,"bash: 9: No such file or directory",[]],"|lt|q":[1,"bash: 9: No such file or directory",[""]],"|lt|dbl":[0,"",null],"|glob|unq":[2,"bash: [: ==: unary operator expected",["==","h*"]],"|glob|q":[1,"",["","==","h*"]],"|glob|dbl":[1,"",null],"hello|eq_str|unq":[0,"",["hello","=","hello"]],"hello|eq_str|q":[0,"",["hello","=","hello"]],"hello|eq_str|dbl":[0,"",null],"hello|eq_num|unq":[2,"bash: [: hello: integer expression expected",["hello","-eq","10"]],"hello|eq_num|q":[2,"bash: [: hello: integer expression expected",["hello","-eq","10"]],"hello|eq_num|dbl":[1,"",null],"hello|n|unq":[0,"",["-n","hello"]],"hello|n|q":[0,"",["-n","hello"]],"hello|n|dbl":[0,"",null],"hello|z|unq":[1,"",["-z","hello"]],"hello|z|q":[1,"",["-z","hello"]],"hello|z|dbl":[1,"",null],"hello|lt|unq":[1,"bash: 9: No such file or directory",["hello"]],"hello|lt|q":[1,"bash: 9: No such file or directory",["hello"]],"hello|lt|dbl":[1,"",null],"hello|glob|unq":[1,"",["hello","==","h*"]],"hello|glob|q":[1,"",["hello","==","h*"]],"hello|glob|dbl":[0,"",null],"a b|eq_str|unq":[2,"bash: [: too many arguments",["a","b","=","hello"]],"a b|eq_str|q":[1,"",["a b","=","hello"]],"a b|eq_str|dbl":[1,"",null],"a b|eq_num|unq":[2,"bash: [: too many arguments",["a","b","-eq","10"]],"a b|eq_num|q":[2,"bash: [: a b: integer expression expected",["a b","-eq","10"]],"a b|eq_num|dbl":[1,"bash: [[: a b: syntax error in expression (error token is \"b\")",null],"a b|n|unq":[2,"bash: [: a: binary operator expected",["-n","a","b"]],"a b|n|q":[0,"",["-n","a b"]],"a b|n|dbl":[0,"",null],"a b|z|unq":[2,"bash: [: a: binary operator expected",["-z","a","b"]],"a b|z|q":[1,"",["-z","a b"]],"a b|z|dbl":[1,"",null],"a b|lt|unq":[1,"bash: 9: No such file or directory",["a","b"]],"a b|lt|q":[1,"bash: 9: No such file or directory",["a b"]],"a b|lt|dbl":[1,"",null],"a b|glob|unq":[2,"bash: [: too many arguments",["a","b","==","h*"]],"a b|glob|q":[1,"",["a b","==","h*"]],"a b|glob|dbl":[1,"",null],"*|eq_str|unq":[2,"bash: [: too many arguments",["notes.md","script.sh","=","hello"]],"*|eq_str|q":[1,"",["*","=","hello"]],"*|eq_str|dbl":[1,"",null],"*|eq_num|unq":[2,"bash: [: too many arguments",["notes.md","script.sh","-eq","10"]],"*|eq_num|q":[2,"bash: [: *: integer expression expected",["*","-eq","10"]],"*|eq_num|dbl":[1,"bash: [[: *: syntax error: operand expected (error token is \"*\")",null],"*|n|unq":[2,"bash: [: notes.md: binary operator expected",["-n","notes.md","script.sh"]],"*|n|q":[0,"",["-n","*"]],"*|n|dbl":[0,"",null],"*|z|unq":[2,"bash: [: notes.md: binary operator expected",["-z","notes.md","script.sh"]],"*|z|q":[1,"",["-z","*"]],"*|z|dbl":[1,"",null],"*|lt|unq":[1,"bash: 9: No such file or directory",["notes.md","script.sh"]],"*|lt|q":[1,"bash: 9: No such file or directory",["*"]],"*|lt|dbl":[0,"",null],"*|glob|unq":[2,"bash: [: too many arguments",["notes.md","script.sh","==","h*"]],"*|glob|q":[1,"",["*","==","h*"]],"*|glob|dbl":[1,"",null],"10|eq_str|unq":[1,"",["10","=","hello"]],"10|eq_str|q":[1,"",["10","=","hello"]],"10|eq_str|dbl":[1,"",null],"10|eq_num|unq":[0,"",["10","-eq","10"]],"10|eq_num|q":[0,"",["10","-eq","10"]],"10|eq_num|dbl":[0,"",null],"10|n|unq":[0,"",["-n","10"]],"10|n|q":[0,"",["-n","10"]],"10|n|dbl":[0,"",null],"10|z|unq":[1,"",["-z","10"]],"10|z|q":[1,"",["-z","10"]],"10|z|dbl":[1,"",null],"10|lt|unq":[1,"bash: 9: No such file or directory",["10"]],"10|lt|q":[1,"bash: 9: No such file or directory",["10"]],"10|lt|dbl":[0,"",null],"10|glob|unq":[1,"",["10","==","h*"]],"10|glob|q":[1,"",["10","==","h*"]],"10|glob|dbl":[1,"",null],"abc|eq_str|unq":[1,"",["abc","=","hello"]],"abc|eq_str|q":[1,"",["abc","=","hello"]],"abc|eq_str|dbl":[1,"",null],"abc|eq_num|unq":[2,"bash: [: abc: integer expression expected",["abc","-eq","10"]],"abc|eq_num|q":[2,"bash: [: abc: integer expression expected",["abc","-eq","10"]],"abc|eq_num|dbl":[1,"",null],"abc|n|unq":[0,"",["-n","abc"]],"abc|n|q":[0,"",["-n","abc"]],"abc|n|dbl":[0,"",null],"abc|z|unq":[1,"",["-z","abc"]],"abc|z|q":[1,"",["-z","abc"]],"abc|z|dbl":[1,"",null],"abc|lt|unq":[1,"bash: 9: No such file or directory",["abc"]],"abc|lt|q":[1,"bash: 9: No such file or directory",["abc"]],"abc|lt|dbl":[1,"",null],"abc|glob|unq":[1,"",["abc","==","h*"]],"abc|glob|q":[1,"",["abc","==","h*"]],"abc|glob|dbl":[1,"",null]};

const opts = (typeof input === "object" && input) || {};
const XS = ["", "hello", "a b", "*", "10", "abc"];
const OPS = {
  eq_str: { label: "= hello", left: true },
  eq_num: { label: "-eq 10", left: true },
  n: { label: "-n (not empty?)", unary: "-n" },
  z: { label: "-z (empty?)", unary: "-z" },
  lt: { label: "< 9", left: true },
  glob: { label: "== h*", left: true },
};
let x = XS.includes(opts.x) ? opts.x : "a b";
let op = OPS[opts.op] ? opts.op : "eq_str";

const root = document.createElement("div");
root.style.cssText = "border:1px solid var(--background-modifier-border);border-radius:10px;padding:12px;font-size:14px;";
dv.container.appendChild(root);
function el(tag, css, text, parent = root) {
  const e = document.createElement(tag);
  if (css) e.style.cssText = css;
  if (text != null) e.textContent = text;
  parent.appendChild(e);
  return e;
}
const mono = "font-family:var(--font-monospace);";

el("div", "font-weight:bold;margin-bottom:6px;", "🧪 [ ] vs [[ ]]: same variable, three ways");
const xRow = el("div", "display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:6px;");
el("span", "color:var(--text-muted);", "x =", xRow);
const xBtns = XS.map((v) => {
  const b = el("button", mono, v === "" ? '"" (empty)' : `"${v}"`, xRow);
  b.onclick = () => { x = v; render(); };
  return b;
});
const opRow = el("div", "display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:8px;");
el("span", "color:var(--text-muted);", "test:", opRow);
const opBtns = Object.entries(OPS).map(([k, o]) => {
  const b = el("button", mono, o.label, opRow);
  b.onclick = () => { op = k; render(); };
  return [k, b];
});
el("div", "font-size:12px;color:var(--text-muted);margin-bottom:8px;", "📁 current folder contains: notes.md  script.sh   (so an unquoted * expands to those two names)");
const cards = el("div", "display:flex;gap:8px;flex-wrap:wrap;");
const why = el("div", "margin-top:10px;padding:8px;border-radius:6px;background:var(--background-secondary);font-size:13px;");

function cmdText(mode) {
  const o = OPS[op];
  const v = mode === "q" ? '"$x"' : "$x";
  const inner = o.unary ? `${o.unary} ${v}` : `${v} ${o.label}`;
  return mode === "dbl" ? `[[ ${inner} ]]` : `[ ${inner} ]`;
}

function verdict(status) {
  if (status === 0) return ["TRUE", "#2b8a3e"];
  if (status === 1) return ["FALSE", "#3b82f6"];
  return ["ERROR", "#d6336c"];
}

function explain() {
  const r = (m) => DATA[`${x}|${op}|${m}`];
  const [su, eu, au] = r("unq");
  const [sq] = r("q");
  const [sd, ed] = r("dbl");
  const lines = [];
  const aq = r("q")[2];
  if (op === "lt") {
    lines.push("In <b>[ ]</b>, <code>&lt; 9</code> is a <b>redirection</b>: bash tries to read input from a file named 9, so <code>[</code> never sees the &lt; at all. (<code>&gt; 9</code> would quietly <b>create</b> a file named 9.)");
    lines.push(`In <b>[[ ]]</b>, &lt; compares <b>strings</b> alphabetically: ${x === "" ? '"" sorts before "9"' : `"${x}" ${sd === 0 ? "sorts before" : "does not sort before"} "9"`}. ${x === "10" ? "That's why <code>[[ 10 &lt; 9 ]]</code> is TRUE: '1' comes before '9'. Use <code>(( x &lt; 9 ))</code> or <code>-lt</code> for numbers." : ""}`);
  } else {
    if (JSON.stringify(au) !== JSON.stringify(aq)) {
      lines.push(x === "" ? "Unquoted empty <code>$x</code> <b>disappears</b>: [ gets one argument fewer." : x === "*" ? "Unquoted <code>$x</code> holds *, which is <b>globbed</b> into the file names." : "Unquoted <code>$x</code> is <b>split on the space</b> into separate words.");
    } else lines.push("Here quoting makes no difference to the arguments (the value has no spaces, no glob characters and isn't empty).");
    if (op === "n" && x === "" ) lines.push("Trap: <code>[ -n $x ]</code> becomes <code>[ -n ]</code>: with one argument, [ only asks \"is '-n' a non-empty string?\" → TRUE. That's why you always quote, or use [[ ]].");
    if (op === "glob") lines.push("<b>[ ]</b> compares <code>==</code> literally (h* is just the text h*). <b>[[ ]]</b> treats an unquoted right side as a <b>pattern</b>, so <code>[[ $x == h* ]]</code> means \"starts with h\".");
    if (op === "eq_num" && sd !== 2) lines.push(`<b>[[ -eq ]]</b> evaluates both sides as <b>arithmetic</b>: ${x === "abc" ? "abc is treated as a variable name, unset → 0, so no error, just FALSE." : x === "" ? "an empty value counts as 0." : ed ? "this value isn't valid arithmetic, so bash prints an error." : "fine for real numbers."}`);
  }
  if (su === 2 && sq !== 2) lines.push("✅ Quoting fixes the error. [[ ]] fixes it too, without quotes on the left side.");
  return lines.join("<br>");
}

function render() {
  xBtns.forEach((b, i) => (b.style.outline = XS[i] === x ? "2px solid var(--interactive-accent)" : ""));
  opBtns.forEach(([k, b]) => (b.style.outline = k === op ? "2px solid var(--interactive-accent)" : ""));
  cards.innerHTML = "";
  for (const [mode, title] of [["unq", "[ unquoted"], ["q", "[ quoted"], ["dbl", "[[ double brackets"]]) {
    const [status, err, args] = DATA[`${x}|${op}|${mode}`];
    const c = el("div", "flex:1 1 180px;min-width:170px;border:1px solid var(--background-modifier-border);border-radius:8px;padding:8px;", null, cards);
    el("div", "font-size:12px;color:var(--text-muted);", title, c);
    el("div", mono + "font-weight:bold;margin:4px 0;", cmdText(mode), c);
    if (args) {
      el("div", "font-size:12px;color:var(--text-muted);", `[ receives ${args.length} argument${args.length === 1 ? "" : "s"} (+ the final ]):`, c);
      const chips = el("div", "display:flex;gap:3px;flex-wrap:wrap;margin:3px 0;", null, c);
      if (!args.length) el("span", "font-size:12px;color:var(--text-faint);", "(none)", chips);
      args.forEach((a) => el("span", mono + "font-size:12px;padding:1px 5px;border-radius:4px;background:var(--background-secondary);", `‹${a}›`, chips));
    } else {
      el("div", "font-size:12px;color:var(--text-muted);margin:3px 0;", "bash syntax: no splitting, no globbing of $x", c);
    }
    const [v, col] = verdict(status);
    el("div", `font-weight:bold;color:${col};margin-top:4px;`, `${v}  ($? = ${status})`, c);
    if (err) el("div", mono + "font-size:11px;color:#d6336c;word-break:break-word;", err, c);
  }
  why.innerHTML = `<b>What happened with x=${x === "" ? '""' : `"${x}"`}:</b><br>` + explain();
}
render();
